  ]},
  {"clause_id": "c012", "issues": [
    {"issue": "\"Any bona fide amounts not in dispute\" is self-limiting and undefined: it does not say who decides whether an amount is bona fide or in dispute, or when the dispute must arise. The offset right's scope therefore has no ascertainable boundary.", "type": 1, "prob": 0.17}
